 "content": "def transform(grid):
    """Trace the 2 path through gaps in successive horizontal 8-barriers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bars = [r for r, row in enumerate(grid) if 8 in row]
    starts = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not starts or not bars:
        return out

    start_r, start_c = starts[0]
    active = [start_c]
    previous_bar = None
    for r in bars:
        gaps = [c for c, value in enumerate(grid[r]) if value == 0]
        if not gaps:
            continue
        if previous_bar is not None:
            # Extend every path from the previous wall down to this corridor.
            for c in active:
                for rr in range(previous_bar + 1, r):
                    if grid[rr][c] == 0:
                        out[rr][c] = 2
        # Join incoming tracks to the openings in this barrier immediately above it.
        row_above = r - 1
        lo, hi = min(active + gaps), max(active + gaps)
        for c in range(lo, hi + 1):
            if grid[row_above][c] == 0:
                out[row_above][c] = 2
        for c in gaps:
            out[r][c] = 2
        active = gaps
        previous_bar = r

    # Continue each final opening to the bottom of the grid.
    if previous_bar is not None:
        for c in active:
            for rr in range(previous_bar + 1, h):
                if grid[rr][c] == 0:
                    out[rr][c] = 2
    return out
