    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bars = [r for r, row in enumerate(grid) if 8 in row]
    starts = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not bars or not starts:
        return out
    start_r, start_c = starts[0]
    gaps = [[c for c, value in enumerate(grid[r]) if value == 0] for r in bars]

    # Top corridor: join the marker's column to all gaps in the first barrier.
    top_y = bars[0] - 1
    for c in range(min([start_c] + gaps[0]), max([start_c] + gaps[0]) + 1):
        if grid[top_y][c] == 0:
            out[top_y][c] = 2

    for i, r in enumerate(bars):
        # The path goes through each gap in the barrier.
        for c in gaps[i]:
            out[r][c] = 2
        # Vertical branches continue through this opening until the next connector.
        if i + 1 < len(bars):
            connector_y = bars[i + 1] - 1
            for c in gaps[i]:
                for y in range(r + 1, connector_y):
                    if grid[y][c] == 0:
                        out[y][c] = 2
            # The lower corridor links all tracks arriving from above to the next set of openings.
            next_gaps = gaps[i + 1]
            left, right = min(gaps[i]), max(gaps[i])
            if len(next_gaps) == 1:
                left, right = 0, w - 1
            else:
                left = min(left, min(next_gaps))
                right = max(right, max(next_gaps))
            for c in range(left, right + 1):
                if grid[connector_y][c] == 0:
                    out[connector_y][c] = 2
        else:
            for c in gaps[i]:
                for y in range(r + 1, h):
                    if grid[y][c] == 0:
                        out[y][c] = 2
    return out
