 "content": "def transform(grid):
    """Draw the 2-path through openings in bands of 8s, using their geometry."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    starts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not starts:
        return out
    sr, sc = starts[0]

    # Detect horizontal bands (rows containing 8s) versus vertical bands
    # (columns containing 8s); each kind is handled by tracing through gaps.
    row_bands = [r for r, row in enumerate(grid) if 8 in row]
    col_bands = [c for c in range(w) if any(grid[r][c] == 8 for r in range(h))]
    if len(row_bands) >= len(col_bands):
        gaps = [[c for c, v in enumerate(grid[r]) if v == 0] for r in row_bands]
        # Start at the marker and connect to first barrier openings.
        r0 = row_bands[0]
        y = r0 - 1
        if y >= sr:
            for c in range(min([sc] + gaps[0]), max([sc] + gaps[0]) + 1):
                if grid[y][c] == 0: out[y][c] = 2
        for i, r in enumerate(row_bands):
            for c in gaps[i]: out[r][c] = 2
            if i + 1 < len(row_bands):
                next_r = row_bands[i + 1]
                y = next_r - 1
                curr, nxt = gaps[i], gaps[i + 1]
                # A single opening on the next band makes a full-width crossbar.
                lo, hi = (0, w - 1) if len(nxt) == 1 else (min(curr + nxt), max(curr + nxt))
                for c in range(lo, hi + 1):
                    if grid[y][c] == 0: out[y][c] = 2
                for c in curr:
                    for rr in range(r + 1, y):
                        if grid[rr][c] == 0: out[rr][c] = 2
            else:
                for c in gaps[i]:
                    for rr in range(r + 1, h):
                        if grid[rr][c] == 0: out[rr][c] = 2
        return out

    # Vertical bands: analogous trace from left to right through 0 openings.
    gaps = [[r for r in range(h) if grid[r][c] == 0] for c in col_bands]
    first_c = col_bands[0]
    # Initial vertical connector from marker row to openings of the first band.
    x = first_c - 1
    if x >= sc:
        for r in range(min([sr] + gaps[0]), max([sr] + gaps[0]) + 1):
            if grid[r][x] == 0: out[r][x] = 2
    for i, c in enumerate(col_bands):
        for r in gaps[i]: out[r][c] = 2
        if i + 1 < len(col_bands):
            next_c = col_bands[i + 1]
            x = next_c - 1
            curr, nxt = gaps[i], gaps[i + 1]
            lo, hi = (0, h - 1) if len(nxt) == 1 else (min(curr + nxt), max(curr + nxt))
            for r in range(lo, hi + 1):
                if grid[r][x] == 0: out[r][x] = 2
            for r in curr:
                for cc in range(c + 1, x):
                    if grid[r][cc] == 0: out[r][cc] = 2
        else:
            for r in gaps[i]:
                for cc in range(c + 1, w):
                    if grid[r][cc] == 0: out[r][cc] = 2
    return out
