 "content": "def transform(grid):
    """Propagate 2-lines through successive horizontal barriers of 8s."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bands = [r for r, row in enumerate(grid) if sum(v == 8 for v in row) >= w // 2]
    starts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not bands or not starts:
        return out
    start_r, start_c = starts[0]
    holes = [[c for c, value in enumerate(grid[r]) if value == 0] for r in bands]

    # Incoming segment reaches the corridor immediately above the first band,
    # then runs across to the opening(s) in that band.
    y = bands[0] - 1
    if y >= start_r and holes[0]:
        left = min([start_c] + holes[0])
        right = max([start_c] + holes[0])
        for c in range(left, right + 1):
            if grid[y][c] == 0:
                out[y][c] = 2

    for i, r in enumerate(bands):
        for c in holes[i]:
            out[r][c] = 2
        if i + 1 < len(bands):
            connector = bands[i + 1] - 1
            current, nxt = holes[i], holes[i + 1]
            if len(nxt) == 1:
                left, right = 0, w - 1
            else:
                left, right = min(current + nxt), max(current + nxt)
            for c in range(left, right + 1):
                if grid[connector][c] == 0:
                    out[connector][c] = 2
            for c in current:
                for rr in range(r + 1, connector):
                    if grid[rr][c] == 0:
                        out[rr][c] = 2
        else:
            for c in holes[i]:
                for rr in range(r + 1, h):
                    if grid[rr][c] == 0:
                        out[rr][c] = 2
    return out
