    """Trace the 2 path through successive horizontal barriers of 8s."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bands = [r for r, row in enumerate(grid) if sum(v == 8 for v in row) >= w // 2]
    markers = [(r, c) for r in range(h) for c, v in enumerate(grid[r]) if v == 2]
    if not bands or not markers:
        return out
    sr, sc = markers[0]
    gaps = [[c for c, v in enumerate(grid[r]) if v == 0] for r in bands]

    # The incoming path reaches the first wall through the corridor above it.
    connector = bands[0] - 1
    if connector >= sr and gaps[0]:
        for c in range(min([sc] + gaps[0]), max([sc] + gaps[0]) + 1):
            if grid[connector][c] == 0:
                out[connector][c] = 2

    # Every opening is painted and continues vertically to the next corridor.
    for i, r in enumerate(bands):
        for c in gaps[i]:
            out[r][c] = 2
        if i + 1 < len(bands):
            connector = bands[i + 1] - 1
            for c in gaps[i]:
                for rr in range(r + 1, connector + 1):
                    if grid[rr][c] == 0:
                        out[rr][c] = 2
            next_gaps = gaps[i + 1]
            if len(next_gaps) == 1:
                left, right = 0, w - 1
            else:
                left = min(gaps[i] + next_gaps)
                right = max(gaps[i] + next_gaps)
            for c in range(left, right + 1):
                if grid[connector][c] == 0:
                    out[connector][c] = 2
        else:
            for c in gaps[i]:
                for rr in range(r + 1, h):
                    if grid[rr][c] == 0:
                        out[rr][c] = 2
    return out
